#include <openssl/evp.h>
#include <openssl/poly1305.h>
#include <openssl/rand.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

static double now(){ struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts); return ts.tv_sec + ts.tv_nsec/1e9; }

#define N 40960000

// ChaCha20_ctr32 signature check
extern void ChaCha20_ctr32(unsigned char *out, const unsigned char *inp, size_t len, const unsigned int key[8], const unsigned int counter[4]);

typedef struct { unsigned char *out; const unsigned char *in; size_t len; unsigned int key[8]; unsigned int counter[4]; } chacha_arg;

static void* chacha_worker(void *a){
    chacha_arg *arg = a;
    ChaCha20_ctr32(arg->out, arg->in, arg->len, arg->key, arg->counter);
    return NULL;
}

int main(){
    unsigned char *key = malloc(32), *nonce = malloc(12), *pt = malloc(N), *ct = malloc(N);
    unsigned char *aad = malloc(32);
    RAND_bytes(key,32); RAND_bytes(nonce,12); RAND_bytes(pt,N); RAND_bytes(aad,32);

    // memcpy bandwidth
    {
        double t0=now();
        for(int i=0;i<5;i++) memcpy(ct, pt, N);
        double t1=now();
        printf("memcpy 40MB x5: %.4f s -> %.2f GB/s (traffic)\n", t1-t0, 5.0*2*N/(t1-t0)/1e9);
    }

    // ChaCha20_ctr32 single thread
    {
        unsigned int key32[8]; memcpy(key32, key, 32);
        unsigned int counter[4] = {1,0,0,0};
        // warm
        ChaCha20_ctr32(ct, pt, N, key32, counter);
        double t0=now();
        for(int i=0;i<5;i++) ChaCha20_ctr32(ct, pt, N, key32, counter);
        double t1=now();
        printf("ChaCha20_ctr32 single x5: %.4f s -> %.2f GB/s\n", t1-t0, 5.0*N/(t1-t0)/1e9);
    }

    // Poly1305 single thread
    {
        unsigned char polykey[32]; RAND_bytes(polykey,32);
        POLY1305 ctx;
        Poly1305_Init(&ctx, polykey);
        Poly1305_Update(&ctx, pt, N);
        unsigned char mac[16];
        double t0=now();
        for(int i=0;i<5;i++){ Poly1305_Init(&ctx, polykey); Poly1305_Update(&ctx, pt, N); Poly1305_Final(&ctx, mac); }
        double t1=now();
        printf("Poly1305 single x5: %.4f s -> %.2f GB/s\n", t1-t0, 5.0*N/(t1-t0)/1e9);
    }

    // ChaCha20_ctr32 multithreaded
    for(int nt=2; nt<=12; nt+=2){
        unsigned int key32[8]; memcpy(key32, key, 32);
        pthread_t th[12]; chacha_arg args[12];
        size_t chunk = N/nt;
        double t0=now();
        for(int i=0;i<nt;i++){
            args[i].out = ct + i*chunk;
            args[i].in = pt + i*chunk;
            args[i].len = (i==nt-1)? (N - i*chunk) : chunk;
            memcpy(args[i].key, key32, 32);
            args[i].counter[0] = 1 + (unsigned int)(i*chunk/64);
            args[i].counter[1]=args[i].counter[2]=args[i].counter[3]=0;
            pthread_create(&th[i], NULL, chacha_worker, &args[i]);
        }
        for(int i=0;i<nt;i++) pthread_join(th[i], NULL);
        double t1=now();
        printf("ChaCha20_ctr32 %d threads: %.4f s -> %.2f GB/s\n", nt, t1-t0, N/(t1-t0)/1e9);
    }
    return 0;
}
